recipes.code:
{
  "inputs": [
    {
      "id": "skopik-api-key",
      "type": "promptString",
      "description": "Skopik API key or user access token.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@skopiklabs/mcp@0.1.0"
      ],
      "env": {
        "SKOPIK_API_KEY": "${input:skopik-api-key}",
        "SKOPIK_API_URL": "<skopik-api-url>"
      }
    }
  }
}
